CREATE TABLE public.offices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL UNIQUE, name text NOT NULL DEFAULT 'GetCryptoDomains.com', paused boolean NOT NULL DEFAULT false, ai_blocked text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.offices TO authenticated; GRANT ALL ON public.offices TO service_role;
ALTER TABLE public.offices ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_office ON public.offices FOR ALL TO authenticated USING (owner_id = auth.uid()) WITH CHECK (owner_id = auth.uid());
CREATE TABLE public.departments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.departments TO authenticated; GRANT ALL ON public.departments TO service_role;
ALTER TABLE public.departments ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_departments ON public.departments FOR ALL TO authenticated USING (owner_id = auth.uid()) WITH CHECK (owner_id = auth.uid());
CREATE TABLE public.projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, name text NOT NULL, domain text NOT NULL DEFAULT '', objective text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.projects TO authenticated; GRANT ALL ON public.projects TO service_role;
ALTER TABLE public.projects ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_projects ON public.projects FOR ALL TO authenticated USING (owner_id = auth.uid()) WITH CHECK (owner_id = auth.uid());
CREATE TABLE public.agents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, name text NOT NULL, role text NOT NULL, kind text NOT NULL CHECK (kind IN ('manager','employee')), department text NOT NULL DEFAULT 'Operations', manager_id uuid, status text NOT NULL DEFAULT 'idle' CHECK (status IN ('idle','paused','retired')), policy text NOT NULL DEFAULT 'Writing and planning only. No external changes.', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.agents TO authenticated; GRANT ALL ON public.agents TO service_role;
ALTER TABLE public.agents ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_agents ON public.agents FOR ALL TO authenticated USING (owner_id = auth.uid()) WITH CHECK (owner_id = auth.uid());
CREATE TABLE public.tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, agent_id uuid REFERENCES public.agents(id), title text NOT NULL, objective text NOT NULL, status text NOT NULL DEFAULT 'awaiting_approval' CHECK (status IN ('awaiting_approval','queued','running','verification','completed','failed','cancelled','blocked')), criteria text NOT NULL DEFAULT '', output text, error text, approved_at timestamptz, run_id text, input_tokens integer, output_tokens integer, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.tasks TO authenticated; GRANT ALL ON public.tasks TO service_role;
ALTER TABLE public.tasks ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_tasks_read ON public.tasks FOR SELECT TO authenticated USING (owner_id = auth.uid());
CREATE TABLE public.audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL, action text NOT NULL, target_id uuid, detail text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_events TO authenticated; GRANT ALL ON public.audit_events TO service_role;
ALTER TABLE public.audit_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_audit_read ON public.audit_events FOR SELECT TO authenticated USING (owner_id = auth.uid());
CREATE INDEX tasks_owner_created ON public.tasks(owner_id,created_at DESC);
CREATE INDEX agents_owner ON public.agents(owner_id);
CREATE INDEX audit_owner_created ON public.audit_events(owner_id,created_at DESC);